package com.procurement.approvalhistory.mapper;import com.procurement.approvalhistory.dto.response.*;import com.procurement.approvalhistory.entity.*;import org.springframework.stereotype.Component;@Component public class ApprovalHistoryMapper{public ApprovalHistoryResponse toResponse(ApprovalHistory e){return new ApprovalHistoryResponse(e.getId(),e.getPurchaseRequest().getId(),e.getPurchaseRequest().getRequestNumber(),e.getApprovalTask()==null?null:e.getApprovalTask().getId(),e.getAction(),e.getPerformedBy().getId(),e.getPerformedBy().getFirstName()+" "+e.getPerformedBy().getLastName(),e.getComments(),e.getPerformedAt());}}
